#include <stdbool.h>

#define N 4

typedef struct {
    int data[N];
    int front;   /* index of oldest element */
    int count;   /* number of stored elements */
} CQueue;

void cq_init(CQueue *q) { q->front = 0; q->count = 0; }
bool cq_empty(const CQueue *q) { return q->count == 0; }
bool cq_full(const CQueue *q)  { return q->count == N; }

bool cq_enqueue(CQueue *q, int x) {
    if (cq_full(q)) return false;
    int rear = (q->front + q->count) % N;   /* next free slot */
    q->data[rear] = x;
    q->count++;
    return true;
}

bool cq_dequeue(CQueue *q, int *out) {
    if (cq_empty(q)) return false;
    *out = q->data[q->front];
    q->front = (q->front + 1) % N;
    q->count--;
    return true;
}

bool cq_peek(const CQueue *q, int *out) {
    if (cq_empty(q)) return false;
    *out = q->data[q->front];
    return true;
}

typedef struct { int d[N]; int head, tail; } Ring;

bool ring_put(Ring *r, int x) {
    int next = (r->tail + 1) % N;
    if (next == r->head) return false;   /* full: N-1 items */
    r->d[r->tail] = x;
    r->tail = next;
    return true;
}
bool ring_get(Ring *r, int *out) {
    if (r->head == r->tail) return false;  /* empty */
    *out = r->d[r->head];
    r->head = (r->head + 1) % N;
    return true;
}

typedef struct {
    int d[8];                 /* N = 8, a power of two */
    unsigned head, tail;      /* free-running counters */
} Fifo;

#define MASK 7u
bool f_put(Fifo *f, int x) {
    if (f->tail - f->head == 8) return false;
    f->d[f->tail++ & MASK] = x;
    return true;
}
bool f_get(Fifo *f, int *out) {
    if (f->tail == f->head) return false;
    *out = f->d[f->head++ & MASK];
    return true;
}
